'use strict';
// Local records are explicitly not an online leaderboard.
const Progression=(()=>{
 const goods={medicine:{name:'구명 금창약',cost:60,text:'다음 출도에서 체력 30% 이하 시 한 번, 체력 25 회복'},incense:{name:'청심향',cost:90,text:'다음 출도 비급 재추첨 +1회'}};
 function normalize(){const d=Profile.data;d.supplies??={medicine:0,incense:0};for(const k of Object.keys(goods))d.supplies[k]=Math.max(0,Math.min(3,Math.floor(Number(d.supplies[k])||0)));d.ranking=Array.isArray(d.ranking)?d.ranking.filter(r=>r&&Number.isFinite(r.kills)&&r.kills>=0).slice(0,50):[]}
 function buy(k){normalize();const g=goods[k],d=Profile.data;if(!g||d.supplies[k]>=3||d.silver<g.cost)return false;d.silver-=g.cost;d.supplies[k]++;Profile.save();updateProfile();return true}
 function begin(s){if(s.preparationApplied||s.demo)return;s.preparationApplied=true;normalize();s.assisted=false;for(const k of Object.keys(goods))if(Profile.data.supplies[k]>0){Profile.data.supplies[k]--;s.assisted=true;if(k==='medicine')s.rescueMedicine=1;else s.rerolls++}if(s.assisted)Profile.save()}
 function update(s){begin(s);if(s.rescueMedicine&&s.p.hp>0&&s.p.hp/s.p.max<=.3){s.rescueMedicine=0;s.p.hp=Math.min(s.p.max,s.p.hp+25);showNotice('구명 금창약 · 체력 +25 · 준비물 소진')}}
 function record(run){normalize();const d=Profile.data;d.ranking.push({...run,date:new Date().toISOString()});d.ranking.sort((a,b)=>b.kills-a.kills||b.time-a.time);d.ranking=d.ranking.slice(0,50)}
 function open(page='supplies',filter='blood'){if(mode!=='menu'&&mode!=='end')return;normalize();$('#camp').hidden=false;$('#campClose').onclick=()=>$('#camp').hidden=true;$('#campTitle').textContent=page==='supplies'?'출도 준비소':'내 기기 처치 랭킹';$('#campSub').textContent=page==='supplies'?'보유 은전 '+Profile.data.silver+' · 각 최대 3개 보관 · 다음 일반 출도에서 종류별 1개 자동 사용':'온라인 경쟁 순위가 아닙니다 · 이 브라우저 기록 최대 50개 · 처치 수 → 생존 시간 순';const box=$('#campContent');box.innerHTML='';
  if(page==='supplies'){for(const [k,g] of Object.entries(goods)){const b=document.createElement('button');b.className='training';b.disabled=Profile.data.supplies[k]>=3||Profile.data.silver<g.cost;b.innerHTML=ItemArt.html(k==='medicine'?'heal':'herb')+'<strong>'+g.name+' · '+g.cost+' 은전</strong><small>'+g.text+'</small><small>보관 '+Profile.data.supplies[k]+'/3 · 클릭하면 1개 구매</small>';b.onclick=()=>{if(buy(k))open('supplies')};box.append(b)}return}
  const nav=document.createElement('div');nav.className='ranking-tabs';for(const id of ['blood','hell']){const b=document.createElement('button');b.textContent=id==='blood'?'혈전':'지옥';b.className=id===filter?'active':'';b.onclick=()=>open('ranking',id);nav.append(b)}box.append(nav);
  const rows=Profile.data.ranking.filter(r=>r.battle===filter);if(!rows.length){const p=document.createElement('p');p.textContent='이 모드의 출도 완료 기록이 아직 없습니다.';box.append(p)}rows.forEach((r,i)=>{const row=document.createElement('div');row.className='ranking-row';const sect=WuxiaUI.SUB_SECTS[r.faction]?.[r.subSect]?.name||factions[r.faction]?.name||'문파';row.textContent=(i+1)+'위 · '+sect+' · '+r.kills+' 처치 · '+format(r.time)+' · '+(stages[r.stage]?.name||'전장')+(r.assisted?' · 준비물 사용':'')+' · 수련 '+(r.training||0)+'단계';box.append(row)})
 }
 return {goods,buy,begin,update,record,open};
})();
function dropSupplies(s,e,rng=Math.random){if(e.supplyRolled||e.boss)return;e.supplyRolled=true;const low=s.p.hp/s.p.max<.4,chance=low?.022:.009;if(s.time<(s.nextSupplyAt||0))return;const n=rng();let type;if(n<chance)type='heal';else if(n<chance+.006)type='qi';else if(n<chance+.009)type='magnet';else return;s.nextSupplyAt=s.time+3;if(s.drops.length<24)s.drops.push({x:e.x,y:e.y,type})}
